def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def request(url):return urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0 PhyCoVE reproducible asset download'}),timeout=90)
def main():
 a=argparse.ArgumentParser();a.add_argument('--out-dir',type=Path,default=ASSETS/'look_assets');o=a.parse_args().out_dir;o.mkdir(parents=True,exist_ok=True)
 for item in MANIFEST['assets']:
  dest=o/item['path'];dest.parent.mkdir(parents=True,exist_ok=True)
  if dest.exists():
   if sha(dest)!=item['sha256']:raise RuntimeError('Existing asset differs: '+str(dest))
   continue
  url=item.get('source_url')
  if not url:
   url=item['download_endpoint']+'?'+urllib.parse.urlencode({'scene_uuid':str(uuid.uuid4())})
   with request(url) as f:response=json.load(f)
   url=response['filePath']
  part=dest.with_suffix(dest.suffix+'.part')
  with request(url) as response,part.open('wb') as output:
   while True:
    block=response.read(1024*1024)
    if not block:break
    output.write(block)
  if sha(part)!=item['sha256']:raise RuntimeError('Downloaded checksum differs: '+item['path'])
  part.rename(dest)
 (o/'metadata').mkdir(exist_ok=True);(o/'metadata/wooden_table_01.json').write_text(METADATA)
